package com.chronos.education.grade.controller;
import com.chronos.commons.model.ResultData; import com.chronos.education.grade.dto.GradeDtos.*; import com.chronos.education.grade.dto.GradeSourceEventContracts.CourseGradesPublishedV1; import com.chronos.education.grade.model.*; import com.chronos.education.grade.service.GradeCenterService; import java.time.OffsetDateTime; import java.util.*; import java.util.UUID; import org.springframework.context.ApplicationEventPublisher; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/admin/education/grades") public class GradeCenterController { private final GradeCenterService service; private final ApplicationEventPublisher events; public GradeCenterController(GradeCenterService service,ApplicationEventPublisher events){this.service=service;this.events=events;}
 @GetMapping("/schemes") @PreAuthorize("hasAuthority('education:score:scheme:view')") public ResultData<List<AssessmentScheme>> schemes(@RequestParam(required=false) String offeringId){return ok(service.listSchemes(offeringId));}
 @PostMapping("/schemes") @PreAuthorize("hasAuthority('education:score:scheme:create')") public ResultData<AssessmentScheme> create(@RequestBody SchemeCommand c,Authentication a){return ok(service.createScheme(c,a.getName()));}
 @PutMapping("/schemes/{id}") @PreAuthorize("hasAuthority('education:score:scheme:update')") public ResultData<AssessmentScheme> update(@PathVariable String id,@RequestBody SchemeCommand c,Authentication a){return ok(service.updateScheme(id,c,a.getName()));}
 @PostMapping("/schemes/{id}/publish") @PreAuthorize("hasAuthority('education:score:scheme:publish')") public ResultData<AssessmentScheme> publishScheme(@PathVariable String id,Authentication a){return ok(service.publishScheme(id,a.getName()));}
 @GetMapping("/gradebooks/{id}") @PreAuthorize("hasAuthority('education:score:gradebook:view')") public ResultData<GradebookDetailResponse> gradebook(@PathVariable String id,Authentication a){return ok(service.getGradebook(id,a.getName()));}
 @GetMapping("/gradebooks/{id}/snapshots") @PreAuthorize("hasAuthority('education:score:gradebook:view')") public ResultData<List<GradePublishSnapshot>> snapshots(@PathVariable String id,Authentication a){return ok(service.snapshots(id,a.getName()));}
 @GetMapping("/gradebooks") @PreAuthorize("hasAuthority('education:score:gradebook:view')") public ResultData<List<Gradebook>> gradebooks(Authentication a){return ok(service.listGradebooks(a.getName()));}
 @PostMapping("/gradebooks") @PreAuthorize("hasAuthority('education:score:gradebook:create')") public ResultData<Gradebook> createGradebook(@RequestBody GradebookCommand c,Authentication a){return ok(service.createGradebook(c,a.getName()));}
 @PutMapping("/gradebooks/{id}/items") @PreAuthorize("hasAuthority('education:score:gradebook:update')") public ResultData<Gradebook> items(@PathVariable String id,@RequestBody ItemsCommand c,Authentication a){return ok(service.saveItems(id,c,a.getName()));}
 @PostMapping("/gradebooks/{id}/submit") @PreAuthorize("hasAuthority('education:score:gradebook:submit')") public ResultData<Gradebook> submit(@PathVariable String id,Authentication a){return ok(service.submit(id,a.getName()));}
 @PostMapping("/gradebooks/{id}/review") @PreAuthorize("hasAuthority('education:score:review')") public ResultData<Gradebook> review(@PathVariable String id,@RequestParam String taskId,@RequestParam boolean approved,@RequestParam(required=false) String comment,Authentication a){return ok(service.review(id,taskId,approved,comment,a.getName()));}
 @PostMapping("/gradebooks/{id}/publish") @PreAuthorize("@iamAuthorization.any(authentication,'education:score:gradebook:publish')") public ResultData<Gradebook> publish(@PathVariable String id,Authentication a){Gradebook gradebook=service.publish(id,a.getName());String snapshotHash=service.snapshots(id,a.getName()).stream().findFirst().map(GradePublishSnapshot::getSnapshotHash).orElseThrow();events.publishEvent(new CourseGradesPublishedV1(UUID.randomUUID().toString(),"CourseGradesPublishedV1",OffsetDateTime.now(),1,gradebook.getId(),gradebook.getOfferingId(),gradebook.getSubmissionNo(),snapshotHash,a.getName()));return ok(gradebook);}
 private <T> ResultData<T> ok(T data){return ResultData.<T>builder().code("200").msg("ok").data(data).build();}
}
